#include <iostream>
#include <vector>
#include <climits>
using namespace std;
int main(){
    int n,m; cin>>n>>m;
    vector<vector<int>> g(n,vector<int>(m));
    for(auto& r:g) for(auto& x:r) cin>>x;
    const long long INF=1e18;
    vector<vector<long long>> dp(n,vector<long long>(m,INF));
    dp[0][0]=g[0][0];
    for(int i=0;i<n;i++) for(int j=0;j<m;j++){
        if(i==0&&j==0) continue;
        if(g[i][j]==-1) continue;
        long long best=INF;
        if(i>0&&dp[i-1][j]!=INF) best=min(best,dp[i-1][j]);
        if(j>0&&dp[i][j-1]!=INF) best=min(best,dp[i][j-1]);
        dp[i][j]=(best==INF)?INF:best+g[i][j];
    }
    cout<<(dp[n-1][m-1]==INF?-1:dp[n-1][m-1])<<"\n";
    return 0;
}

